using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve EF8 discriminator property name (EF9 defaults to "$type")
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Preserve EF8 compound id format "Blog|1" (EF9 defaults to key-only)
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

        // REMOVED: HasIndex throws at startup in EF9 Cosmos provider.
        // Manage indexing via Azure Portal or IaC (Bicep/Terraform).
    }
}
